import { io } from 'socket.io-client';

const socket = io('http://localhost:3000', {
	autoConnect: false,
	reconnection: true,
	reconnectionDelay: 1000,
	reconnectionDelayMax: 5000,
	reconnectionAttempts: 5
});

// Handle authentication
socket.on('connect', () => {
	console.log('Connected to server');
	const token = localStorage.getItem('token');
	if (token) {
		socket.emit('authenticate', token);
	}
});

socket.on('authenticated', () => {
	console.log('Socket authenticated successfully');
	// Si l'utilisateur est admin, vérifier les droits
	if (localStorage.getItem('isAdmin') === 'true') {
		socket.emit('verifyAdminRights');
	}
});

socket.on('adminRightsVerified', () => {
	console.log('Admin rights verified successfully');
});

socket.on('requestReceived', (data) => {
	console.log('Requête reçue par le serveur:', data);
});

socket.on('disconnect', () => {
	console.log('Disconnected from server');
});

socket.on('error', (error) => {
	console.error('Socket error:', error);
});

export { socket };
